import { BufferGeometry } from "three/src/core/BufferGeometry.js";
import { Object3D } from "../../core/Object3D.js";
import { Material } from "three/src/materials/Material.js";
import Renderer from "three/src/renderers/common/Renderer.js";
import RenderPipeline from "three/src/renderers/common/RenderPipeline.js";
import ComputeNode from "three/src/nodes/gpgpu/ComputeNode.js";

export default abstract class NodeBuilder {
    object: Object3D;
    material: Material;
    geometry: BufferGeometry;

    /**
     * The compute node, if building for compute.
     */
    compute: ComputeNode | null;

    renderer: Renderer;
    context: unknown;

    /**
     * A reference to the render pipeline.
     */
    readonly renderPipeline: RenderPipeline;
}
